 26	/*
 27	 * The receive completion interrupt is delivered on whichever hart happens to
 28	 * be running, in whatever address space happens to be installed -- and with
 29	 * SUM cleared, so the handler cannot touch user memory at all.  It therefore
 30	 * drops the frames into this kernel staging area, and do_net_recv() hands
 31	 * them over once the caller has been scheduled again.
 32	 */
 33	static EthernetFrame recv_stage[RXBD_CNT];
 34	static size_t recv_stage_len[RXBD_CNT];
