 36	long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
 37	{
 38	    // receive packet by calling network driver's function
 39	    // wait until you receive enough packets(`num_packet`).
 40	    if(num_packet <= 0 || num_packet > RXBD_CNT){
 41	        return -1;
 42	    }
 43	
 44	    /* interrupts must stay off until we are queued on net_recv_queue,
 45	     * otherwise the handler would wake up an empty queue */
 46	    disable_preempt();
 47	
 48	    recv_transaction = 1;
 49	    enable_sum();
 50	    for(int i = 0; i < num_packet; i++){
 51	        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
 52	        rx_len[i] = 0;
 53	    }
 54	    EmacPsRecv(&EmacPsInstance, 0, num_packet);
 55	
 56	    if(net_poll_mode == 0){
 57	        /* poll mode: spin until every descriptor has been handed back */
 58	        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);
 59	        rx_curr = addr;
 60	        rx_tail = 0;
 61	        for(int i = 0; i < num_packet; i++){
 62	            memcpy((uint8_t*)rx_curr, (uint8_t*)&rx_buffers[i], rx_len[i]);
 63	            *(frLength + i) = rx_len[i];
 64	            rx_curr += rx_len[i];
 65	            rx_tail += rx_len[i];
 66	        }
 67	        recv_transaction = 0;
 68	        disable_sum();
 69	        enable_preempt();
 70	        return rx_tail;
 71	    }
 72	    else if(net_poll_mode == 1){
 73	        /* interrupt mode: sleep until XEmacPsRecvHandler() has staged the
 74	         * frames for us, then copy them out in our own address space */
 75	        _addr = (uintptr_t)recv_stage;
 76	        _num_packet = num_packet;
 77	        _frLength = recv_stage_len;
 78	        do_block(&current_running[cpu_id]->list, &net_recv_queue);
 79	        disable_sum();
 80	        scheduler();
 81	        enable_preempt();
 82	
 83	        enable_sum();
 84	        rx_curr = addr;
 85	        rx_tail = 0;
 86	        for(int i = 0; i < num_packet; i++){
 87	            memcpy((uint8_t*)rx_curr, (uint8_t*)recv_stage + rx_tail, recv_stage_len[i]);
 88	            *(frLength + i) = recv_stage_len[i];
 89	            rx_curr += recv_stage_len[i];
 90	            rx_tail += recv_stage_len[i];
 91	        }
 92	        disable_sum();
 93	        return rx_tail;
 94	    }
 95	    else{
 96	        recv_transaction = 0;
 97	        disable_sum();
 98	        enable_preempt();
 99	        return -1;
100	    }
101	}
