103	void do_net_send(uintptr_t addr, size_t length)
104	{
105	    // send all packet
106	    disable_preempt();
107	
108	    send_transaction = 1;
109	    enable_sum();
110	    memset(&tx_buffer, 0, sizeof(EthernetFrame));
111	    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, length);
112	    EmacPsSend(&EmacPsInstance, 0, length);
113	
114	    if(net_poll_mode == 0){
115	        EmacPsWaitSend(&EmacPsInstance);
116	        send_transaction = 0;
117	        disable_sum();
118	    }
119	    else if(net_poll_mode == 1){
120	        /* XEmacPsSendHandler() wakes us up once the frame has left */
121	        do_block(&current_running[cpu_id]->list, &net_send_queue);
122	        disable_sum();
123	        scheduler();
124	    }
125	    else{
126	        send_transaction = 0;
127	        disable_sum();
128	    }
129	
130	    enable_preempt();
131	}
