 25	void shm_read(char* shmbuf, atomic_long *_available, char* buf, size_t size)
 26	{
 27	    while (size > 0) {
 28	        while(atomic_load_d(_available) != 1);
 29	
 30	        int sz = size > FIFO_BUF_MAX ? FIFO_BUF_MAX : size;
 31	        memcpy(buf, shmbuf, sz);
 32	        size -= sz;
 33	
 34	        atomic_exchange_d(_available, 0);
 35	    }
 36	}
